#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeSignalClient: FfiConverter {
    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = SignalClient

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> SignalClient {
        return SignalClient(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: SignalClient) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SignalClient {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if ptr == nil {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: SignalClient, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypeSignalClient_lift(_ pointer: UnsafeMutableRawPointer) throws -> SignalClient {
    return try FfiConverterTypeSignalClient.lift(pointer)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypeSignalClient_lower(_ value: SignalClient) -> UnsafeMutableRawPointer {
    return FfiConverterTypeSignalClient.lower(value)
}

/**
 * Represents a message attachment (image, video, file, etc.)
 */
public struct Attachment {
    /**
     * MIME content type (e.g. "image/jpeg", "video/mp4")
     */
    public var contentType: String
    /**
     * File path on disk (None if download failed)
     */
    public var filePath: String?
    /**
     * Original file name (if available)
     */
    public var fileName: String?
    /**
     * Width in pixels (for images/videos)
     */
    public var width: UInt32?
    /**
     * Height in pixels (for images/videos)
     */
    public var height: UInt32?
    /**
     * File size in bytes
     */
    public var size: UInt32?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * MIME content type (e.g. "image/jpeg", "video/mp4")
         */ contentType: String,
        /**
            * File path on disk (None if download failed)
            */ filePath: String?,
        /**
            * Original file name (if available)
            */ fileName: String?,
        /**
            * Width in pixels (for images/videos)
            */ width: UInt32?,
        /**
            * Height in pixels (for images/videos)
            */ height: UInt32?,
        /**
            * File size in bytes
            */ size: UInt32?
    ) {
        self.contentType = contentType
        self.filePath = filePath
        self.fileName = fileName
        self.width = width
        self.height = height
        self.size = size
    }
}

extension Attachment: Equatable, Hashable {
    public static func == (lhs: Attachment, rhs: Attachment) -> Bool {
        if lhs.contentType != rhs.contentType {
            return false
        }
        if lhs.filePath != rhs.filePath {
            return false
        }
        if lhs.fileName != rhs.fileName {
            return false
        }
        if lhs.width != rhs.width {
            return false
        }
        if lhs.height != rhs.height {
            return false
        }
        if lhs.size != rhs.size {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(contentType)
        hasher.combine(filePath)
        hasher.combine(fileName)
        hasher.combine(width)
        hasher.combine(height)
        hasher.combine(size)
    }
}

